-- =============================================================================
-- Baseerah Quran Vocabulary Migration & Seed
-- Run this script in the Supabase Dashboard SQL Editor
-- (https://supabase.com/dashboard/project/yxqdquynlgfbxyultsux/sql)
-- =============================================================================

-- ── Add 'vocab' (مفردات وغريب القرآن الكريم) to CMS content kinds ─────────────
alter table public.content_items drop constraint if exists content_items_kind_check;
alter table public.content_items
  add constraint content_items_kind_check
  check (kind in ('lesson', 'evidence', 'quote', 'vocab', 'story', 'sharia', 'adhkar', 'tafsir', 'tajweed', 'drill', 'path', 'map', 'page', 'book', 'audio'));

/** Extend public.cms_check to validate 'vocab' slots. */
create or replace function public.cms_check(k text, slot text, d jsonb, p_publish boolean) returns text
language plpgsql immutable as $$
declare q jsonb; x jsonb; n int; ids text[] := '{}';
begin
  if jsonb_typeof(d) <> 'object' then return 'data_not_object'; end if;
  case k
  when 'lesson' then
    if slot !~ '^(AQ|FQ|TF|HD|SR|TZ)-\d{2}$' then return 'bad_slot'; end if;
    if public.cms_blank(d->'title') then return 'title_required'; end if;
    if coalesce((d#>>'{quiz,passPct}')::int, 0) not between 50 and 100 then return 'pass_pct'; end if;
    for q in select * from jsonb_array_elements(coalesce(d#>'{quiz,questions}', '[]')) loop
      n := jsonb_array_length(coalesce(q->'options', '[]'));
      if public.cms_blank(q->'id') or q->>'id' = any (ids) then return 'question_id'; end if;
      ids := ids || (q->>'id');
      if public.cms_blank(q->'q') or n not between 2 and 6 or coalesce((q->>'answer')::int, -1) not between 0 and n - 1 then return 'question_invalid'; end if;
    end loop;
    if p_publish and (jsonb_array_length(coalesce(d->'objectives', '[]')) = 0 or jsonb_array_length(coalesce(d->'sections', '[]')) = 0
                      or jsonb_array_length(coalesce(d#>'{quiz,questions}', '[]')) = 0) then return 'lesson_incomplete'; end if;
  when 'evidence' then
    if slot !~ '^(AQ|FQ|TF|HD|SR|TZ)-\d{2}/e\d+$' then return 'bad_slot'; end if;
    if p_publish and (public.cms_blank(d->'text') or public.cms_blank(d->'source')) then return 'source_required'; end if;
  when 'quote' then
    if p_publish and (public.cms_blank(d->'text') or public.cms_blank(d->'scholar') or public.cms_blank(d->'source')) then return 'source_required'; end if;
  when 'vocab' then
    if public.cms_blank(d->'word') or public.cms_blank(d->'meaning') then return 'word_required'; end if;
    if p_publish and (jsonb_array_length(coalesce(d->'ayahs', '[]')) = 0) then return 'source_required'; end if;
  when 'story', 'sharia' then
    if p_publish then
      n := 0;
      for x in select value from jsonb_each(coalesce(d->'sections', '{}')) loop
        if public.cms_blank(x->'text') or public.cms_blank(x->'source') then return 'source_required'; end if;
        n := n + 1;
      end loop;
      if n = 0 then return 'empty'; end if;
    end if;
  when 'adhkar' then
    for x in select * from jsonb_array_elements(coalesce(d->'items', '[]')) loop
      if public.cms_blank(x->'id') or x->>'id' = any (ids) then return 'item_id'; end if;
      ids := ids || (x->>'id');
      if p_publish and (public.cms_blank(x->'text') or public.cms_blank(x->'source') or coalesce((x->>'count')::int, 0) < 1) then return 'source_required'; end if;
    end loop;
    if p_publish and cardinality(ids) = 0 then return 'empty'; end if;
  when 'tafsir' then
    if slot !~ '^\d{1,3}$' or slot::int not between 1 and 114 then return 'bad_slot'; end if;
    if p_publish and (public.cms_blank(d->'source') or public.cms_blank(d->'tafsir') or coalesce(d->'ayahs', '{}') = '{}') then return 'source_required'; end if;
  when 'tajweed' then
    if p_publish and (public.cms_blank(d->'text') or public.cms_blank(d->'source')) then return 'source_required'; end if;
  when 'drill' then
    for q in select * from jsonb_array_elements(coalesce(d->'questions', '[]')) loop
      n := jsonb_array_length(coalesce(q->'options', '[]'));
      if public.cms_blank(q->'id') or n not between 2 and 6 or coalesce((q->>'answer')::int, -1) not between 0 and n - 1 then return 'question_invalid'; end if;
      if p_publish and (public.cms_blank(q->'audio') or public.cms_blank(q->'source')) then return 'source_required'; end if;
    end loop;
  when 'path' then
    if p_publish and jsonb_array_length(coalesce(d->'steps', '[]')) = 0 then return 'empty'; end if;
  when 'map' then
    if p_publish and jsonb_array_length(coalesce(d->'links', '[]')) = 0 then return 'empty'; end if;
  when 'page' then
    if p_publish and jsonb_array_length(coalesce(d->'sections', '[]')) = 0 then return 'empty'; end if;
  when 'book' then
    if public.cms_blank(d->'title') then return 'title_required'; end if;
    if p_publish and (public.cms_blank(d->'source') or jsonb_array_length(coalesce(d->'chapters', '[]')) = 0) then return 'source_required'; end if;
  when 'audio' then
    if public.cms_blank(d->'title') then return 'title_required'; end if;
    if p_publish and (public.cms_blank(d->'source') or coalesce(d->>'audio_url', '') !~ '^https://') then return 'source_required'; end if;
  else
    return 'unknown_kind';
  end case;
  return null;
end;
$$;


-- ── Insert & Publish Initial Quran Vocabulary ────────────────────────────────

insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'taghut', 'الطَّاغُوت', 'العقيدة', 'تفسير القرآن العظيم لابن كثير (1/688)', '{"id":"taghut","word":"الطَّاغُوت","root":"ط غ ي","category":"العقيدة","meaning":"كل ما عُبد أو أُطيع أو اتُّبع من دون الله تعالى وهو راضٍ، أو ما تجاوز به العبد حده من معبود أو متبوع أو مطاع.","ayahs":[{"surah":2,"ayah":256,"surahName":"البقرة","text":"فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":"تفسير ابن كثير: أي من خلع الأنداد والأوثان وما يدعو إليه الشيطان من عبادة غير الله، ووحّد الله وعبده وحده وشهد أن لا إله إلا هو؛ فقد ثبت على أصح الطرق واستمسك بأوثق عروة لا تنقطع.","source":"تفسير القرآن العظيم لابن كثير (1/688)","wajh":"تقديم الكفر بالطاغوت على الإيمان بالله في الآية دليل صريح على أن التوحيد لا يصح ولا يُقبل إلا بالبراءة التامة من الشرك وأهله ومعبوداته الباطلة أولاً."},{"surah":16,"ayah":36,"surahName":"النحل","text":"وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ","tafsir":"تفسير السعدي: هذا مقصود دعوة الرسل قاطبة؛ الأمر بعبادة الله وحده لا شريك له، والنهي التام عن عبادة الطاغوت واجتنابه بالكلية.","source":"تيسير الكريم الرحمن للسعدي (ص 440)","wajh":"الاجتناب أبلغ من مجرد الترك؛ فهو يقتضي المباعدة بالقلب واللسان والعمل، ويدل على أن اجتناب الطاغوت هو مقتضى شهادة أن لا إله إلا الله."},{"surah":4,"ayah":60,"surahName":"النساء","text":"أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوا إِلَى الطَّاغُوتِ وَقَدْ أُمِرُوا أَن يَكْفُرُوا بِهِ","tafsir":"تفسير ابن كثير: ذم الله من يدعي الإيمان ثم يعدل عن كتاب الله وسنة رسوله في التحاكم إلى حكم الجاهلية والطواغيت من الحكام والقوانين الوضعية المخالفة للشرع.","source":"تفسير ابن كثير (2/346)","wajh":"تسمية الحاكم بغير ما أنزل الله طاغوتاً، وبيان أن التحاكم إلى غير شرع الله يناقض دعوى الإيمان ويخالف الأمر الإلهي بالكفر بالطاغوت."}],"quotes":[{"scholar":"أمير المؤمنين عمر بن الخطاب رضي الله عنه","text":"الجبت: السحر، والطاغوت: الشيطان.","source":"رواه ابن أبي شيبة والطبري بإسناد صحيح"},{"scholar":"الإمام مالك بن أنس رحمه الله","text":"الطاغوت: هو كل ما يُعبد من دون الله عز وجل.","source":"رواه ابن أبي حاتم في تفسيره"},{"scholar":"الإمام ابن القيم رحمه الله","text":"الطاغوت: كل ما تجاوز به العبد حده من معبود، أو متبوع، أو مطاع؛ فطاغوت كل قوم من يتحاكمون إليه غير الله ورسوله، أو يعبدونه من دون الله، أو يتبعونه على غير بصيرة من الله.","source":"إعلام الموقعين عن رب العالمين (1/40)"},{"scholar":"الشيخ محمد بن عبد الوهاب رحمه الله","text":"والطواغيت كثيرة، ورؤوسهم خمسة: إبليس لعنه الله، ومن عُبد وهو راضٍ، ومن دعا الناس إلى عبادة نفسه، ومن ادعى شيئاً من علم الغيب، ومن حكم بغير ما أنزل الله.","source":"رسالة في معنى الطاغوت"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"taghut","word":"الطَّاغُوت","root":"ط غ ي","category":"العقيدة","meaning":"كل ما عُبد أو أُطيع أو اتُّبع من دون الله تعالى وهو راضٍ، أو ما تجاوز به العبد حده من معبود أو متبوع أو مطاع.","ayahs":[{"surah":2,"ayah":256,"surahName":"البقرة","text":"فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ","tafsir":"تفسير ابن كثير: أي من خلع الأنداد والأوثان وما يدعو إليه الشيطان من عبادة غير الله، ووحّد الله وعبده وحده وشهد أن لا إله إلا هو؛ فقد ثبت على أصح الطرق واستمسك بأوثق عروة لا تنقطع.","source":"تفسير القرآن العظيم لابن كثير (1/688)","wajh":"تقديم الكفر بالطاغوت على الإيمان بالله في الآية دليل صريح على أن التوحيد لا يصح ولا يُقبل إلا بالبراءة التامة من الشرك وأهله ومعبوداته الباطلة أولاً."},{"surah":16,"ayah":36,"surahName":"النحل","text":"وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ","tafsir":"تفسير السعدي: هذا مقصود دعوة الرسل قاطبة؛ الأمر بعبادة الله وحده لا شريك له، والنهي التام عن عبادة الطاغوت واجتنابه بالكلية.","source":"تيسير الكريم الرحمن للسعدي (ص 440)","wajh":"الاجتناب أبلغ من مجرد الترك؛ فهو يقتضي المباعدة بالقلب واللسان والعمل، ويدل على أن اجتناب الطاغوت هو مقتضى شهادة أن لا إله إلا الله."},{"surah":4,"ayah":60,"surahName":"النساء","text":"أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوا إِلَى الطَّاغُوتِ وَقَدْ أُمِرُوا أَن يَكْفُرُوا بِهِ","tafsir":"تفسير ابن كثير: ذم الله من يدعي الإيمان ثم يعدل عن كتاب الله وسنة رسوله في التحاكم إلى حكم الجاهلية والطواغيت من الحكام والقوانين الوضعية المخالفة للشرع.","source":"تفسير ابن كثير (2/346)","wajh":"تسمية الحاكم بغير ما أنزل الله طاغوتاً، وبيان أن التحاكم إلى غير شرع الله يناقض دعوى الإيمان ويخالف الأمر الإلهي بالكفر بالطاغوت."}],"quotes":[{"scholar":"أمير المؤمنين عمر بن الخطاب رضي الله عنه","text":"الجبت: السحر، والطاغوت: الشيطان.","source":"رواه ابن أبي شيبة والطبري بإسناد صحيح"},{"scholar":"الإمام مالك بن أنس رحمه الله","text":"الطاغوت: هو كل ما يُعبد من دون الله عز وجل.","source":"رواه ابن أبي حاتم في تفسيره"},{"scholar":"الإمام ابن القيم رحمه الله","text":"الطاغوت: كل ما تجاوز به العبد حده من معبود، أو متبوع، أو مطاع؛ فطاغوت كل قوم من يتحاكمون إليه غير الله ورسوله، أو يعبدونه من دون الله، أو يتبعونه على غير بصيرة من الله.","source":"إعلام الموقعين عن رب العالمين (1/40)"},{"scholar":"الشيخ محمد بن عبد الوهاب رحمه الله","text":"والطواغيت كثيرة، ورؤوسهم خمسة: إبليس لعنه الله، ومن عُبد وهو راضٍ، ومن دعا الناس إلى عبادة نفسه، ومن ادعى شيئاً من علم الغيب، ومن حكم بغير ما أنزل الله.","source":"رسالة في معنى الطاغوت"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
on conflict (kind, slot) do update set
  title = excluded.title,
  category = excluded.category,
  source = excluded.source,
  data = excluded.data,
  published_data = excluded.published_data,
  published_at = excluded.published_at,
  status = 'published',
  approver_names = excluded.approver_names;

insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'fasiq', 'الْفَاسِق / الْفِسْق', 'العقيدة والأحكام', 'تفسير القرآن العظيم (4/173)', '{"id":"fasiq","word":"الْفَاسِق / الْفِسْق","root":"ف س ق","category":"العقيدة والأحكام","meaning":"أصله في لغة العرب: الخروج عن الشيء؛ وفي الشرع: الخروج عن طاعة الله وأمره. وهو قسمان: فسق أكبر مخرج من الملة (كفسق إبليس والكفار والمنافقين)، وفسق أصغر لا يخرج من الملة (وهو ارتكاب الكبائر دون استحلال).","ayahs":[{"surah":9,"ayah":67,"surahName":"التوبة","text":"إِنَّ الْمُنَافِقِينَ هُمُ الْفَاسِقُونَ","tafsir":"تفسير ابن كثير: أي الخارجون عن طاعة الله، المارقون عن دين الحق، المتمردون على شريعته خروج كفر وردة.","source":"تفسير القرآن العظيم (4/173)","wajh":"حصر الفسق في المنافقين بلام التعريف للدلالة على الفسق الأكبر المخرج من ملة الإسلام بالكلية."},{"surah":49,"ayah":6,"surahName":"الحجرات","text":"يَا أَيُّهَا الَّذِينَ آمَنُوا إِن جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَن تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَىٰ مَا فَعَلْتُمْ نَادِمِينَ","tafsir":"تفسير السعدي: دلت الآية على وجوب التثبت في خبر الفاسق، ورد خبره حتى يتبين صدقه بقرائن أخرى، لأن الفسق مانع من قبول الشهادة والرواية في الدين.","source":"تيسير الكريم الرحمن (ص 799)","wajh":"جاء الفسق هنا مراداً به الفسق الأصغر (المعصية دون الكفر)، بدليل نداء المؤمنين بخطاب الإيمان وأمرهم بالتثبت في الأخبار صيانة لدماء المسلمين وأعراضهم."},{"surah":32,"ayah":18,"surahName":"السجدة","text":"أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا ۚ لَّا يَسْتَوُونَ","tafsir":"تفسير الطبري: لا يستوي عند الله في الدار الآخرة المؤمن المطيع الموحد، والفاسق الكافر الخارج عن أمر ربه المكذب بآياته.","source":"جامع البيان في تأويل القرآن (20/188)","wajh":"المقابلة التامة في الآية بين «مؤمناً» و«فاسقاً» تبين أن الفسق إذا قوبل بأصل الإيمان كان كفراً وشركاً أكبر."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الفسق في كتاب الله على وجهين: فسق كفر، وفسق معصية.","source":"رواه ابن أبي حاتم والدر المنثور"},{"scholar":"شيخ الإسلام ابن تيمية رحمه الله","text":"الفسق أصله الخروج عن الطاعة؛ فإن كان خروجاً كلياً كان كفراً، وإن كان خروجاً في بعض المأمورات أو ارتكاب بعض المنهيات كان فسقاً لا يخرج من الإيمان بالكلية.","source":"مجموع الفتاوى (7/171)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"fasiq","word":"الْفَاسِق / الْفِسْق","root":"ف س ق","category":"العقيدة والأحكام","meaning":"أصله في لغة العرب: الخروج عن الشيء؛ وفي الشرع: الخروج عن طاعة الله وأمره. وهو قسمان: فسق أكبر مخرج من الملة (كفسق إبليس والكفار والمنافقين)، وفسق أصغر لا يخرج من الملة (وهو ارتكاب الكبائر دون استحلال).","ayahs":[{"surah":9,"ayah":67,"surahName":"التوبة","text":"إِنَّ الْمُنَافِقِينَ هُمُ الْفَاسِقُونَ","tafsir":"تفسير ابن كثير: أي الخارجون عن طاعة الله، المارقون عن دين الحق، المتمردون على شريعته خروج كفر وردة.","source":"تفسير القرآن العظيم (4/173)","wajh":"حصر الفسق في المنافقين بلام التعريف للدلالة على الفسق الأكبر المخرج من ملة الإسلام بالكلية."},{"surah":49,"ayah":6,"surahName":"الحجرات","text":"يَا أَيُّهَا الَّذِينَ آمَنُوا إِن جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَن تُصِيبُوا قَوْمًا بِجَهَالَةٍ فَتُصْبِحُوا عَلَىٰ مَا فَعَلْتُمْ نَادِمِينَ","tafsir":"تفسير السعدي: دلت الآية على وجوب التثبت في خبر الفاسق، ورد خبره حتى يتبين صدقه بقرائن أخرى، لأن الفسق مانع من قبول الشهادة والرواية في الدين.","source":"تيسير الكريم الرحمن (ص 799)","wajh":"جاء الفسق هنا مراداً به الفسق الأصغر (المعصية دون الكفر)، بدليل نداء المؤمنين بخطاب الإيمان وأمرهم بالتثبت في الأخبار صيانة لدماء المسلمين وأعراضهم."},{"surah":32,"ayah":18,"surahName":"السجدة","text":"أَفَمَن كَانَ مُؤْمِنًا كَمَن كَانَ فَاسِقًا ۚ لَّا يَسْتَوُونَ","tafsir":"تفسير الطبري: لا يستوي عند الله في الدار الآخرة المؤمن المطيع الموحد، والفاسق الكافر الخارج عن أمر ربه المكذب بآياته.","source":"جامع البيان في تأويل القرآن (20/188)","wajh":"المقابلة التامة في الآية بين «مؤمناً» و«فاسقاً» تبين أن الفسق إذا قوبل بأصل الإيمان كان كفراً وشركاً أكبر."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الفسق في كتاب الله على وجهين: فسق كفر، وفسق معصية.","source":"رواه ابن أبي حاتم والدر المنثور"},{"scholar":"شيخ الإسلام ابن تيمية رحمه الله","text":"الفسق أصله الخروج عن الطاعة؛ فإن كان خروجاً كلياً كان كفراً، وإن كان خروجاً في بعض المأمورات أو ارتكاب بعض المنهيات كان فسقاً لا يخرج من الإيمان بالكلية.","source":"مجموع الفتاوى (7/171)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
