insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'jibt', 'الْجِبْت', 'العقيدة', 'تفسير القرآن العظيم (2/338)', '{"id":"jibt","word":"الْجِبْت","root":"ج ب ت","category":"العقيدة","meaning":"كل ما لا خير فيه؛ ويُطلق شرعاً على السحر، والكهانة، والأصنام، وحيل الشياطين وكل معبود أو معظم من دون الله تعالى.","ayahs":[{"surah":4,"ayah":51,"surahName":"النساء","text":"أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا هَٰؤُلَاءِ أَهْدَىٰ مِنَ الَّذِينَ آمَنُوا سَبِيلًا","tafsir":"تفسير ابن كثير: ذم الله تعالى أهل الكتاب الذين آتاهم العلم ثم مالوا إلى تصديق الجبت والطاغوت وممالأة المشركين على أهل التوحيد والإيمان.","source":"تفسير القرآن العظيم (2/338)","wajh":"التحذير البالغ من تصديق خرافات الكهان والسحرة وعبادة الأوثان، وبيان أن العلم لا ينفع صاحبه إن لم يقترن بالإخلاص والبراءة من الشرك."}],"quotes":[{"scholar":"أمير المؤمنين عمر بن الخطاب رضي الله عنه","text":"الجبت: السحر، والطاغوت: الشيطان.","source":"صحيح البخاري تعليقاً برقم 4583"},{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الجبت: الأصنام، والطاغوت: الذين يكونون بين أيديهم يضلون الناس.","source":"تفسير الطبري (8/462)"},{"scholar":"مجاهد بن جبر رحمه الله","text":"الجبت: السحر والشيطان في صورة إنسان.","source":"تفسير مجاهد (1/165)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"jibt","word":"الْجِبْت","root":"ج ب ت","category":"العقيدة","meaning":"كل ما لا خير فيه؛ ويُطلق شرعاً على السحر، والكهانة، والأصنام، وحيل الشياطين وكل معبود أو معظم من دون الله تعالى.","ayahs":[{"surah":4,"ayah":51,"surahName":"النساء","text":"أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا هَٰؤُلَاءِ أَهْدَىٰ مِنَ الَّذِينَ آمَنُوا سَبِيلًا","tafsir":"تفسير ابن كثير: ذم الله تعالى أهل الكتاب الذين آتاهم العلم ثم مالوا إلى تصديق الجبت والطاغوت وممالأة المشركين على أهل التوحيد والإيمان.","source":"تفسير القرآن العظيم (2/338)","wajh":"التحذير البالغ من تصديق خرافات الكهان والسحرة وعبادة الأوثان، وبيان أن العلم لا ينفع صاحبه إن لم يقترن بالإخلاص والبراءة من الشرك."}],"quotes":[{"scholar":"أمير المؤمنين عمر بن الخطاب رضي الله عنه","text":"الجبت: السحر، والطاغوت: الشيطان.","source":"صحيح البخاري تعليقاً برقم 4583"},{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الجبت: الأصنام، والطاغوت: الذين يكونون بين أيديهم يضلون الناس.","source":"تفسير الطبري (8/462)"},{"scholar":"مجاهد بن جبر رحمه الله","text":"الجبت: السحر والشيطان في صورة إنسان.","source":"تفسير مجاهد (1/165)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
