insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'samad', 'الصَّمَد', 'العقيدة', 'تيسير الكريم الرحمن (ص 937)', '{"id":"samad","word":"الصَّمَد","root":"ص م د","category":"العقيدة","meaning":"السيد العظيم الذي انتهى سؤدده وعظمته، والذي تصمد إليه الخلائق قاطبة في حوائجها ورغائبها، والغني بذاته عن كل ما سواه سبحانه، الذي لا جوف له ولا يطعم.","ayahs":[{"surah":112,"ayah":2,"surahName":"الإخلاص","text":"اللَّهُ الصَّمَدُ","tafsir":"تفسير السعدي: أي المقصود في جميع الحوائج؛ فأهل السماوات والأرض مفتقرون إليه غاية الافتقار، يسألونه حوائجهم ويعولون عليه في أمورهم، لأنه الكامل في أوصافه العليم الذي كمل في علمه، الرحيم الذي كمل في رحمته.","source":"تيسير الكريم الرحمن (ص 937)","wajh":"إثبات كمال غنى الرب تبارك وتعالى وكمال فقر جميع المخلوقات إليه، وتفرده سبحانه بالألوهية واستحقاق إخلاص الدعاء والاستعانة له وحده لا شريك له."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الصمد: السيد الذي قد كمل في سؤدده، والشريف الذي قد كمل في شرفه، والعظيم الذي قد كمل في عظمته، وهو الله سبحانه، هذه صفته لا تنبغي إلا له.","source":"تفسير ابن كثير (8/500)"},{"scholar":"الحسن البصري رحمه الله","text":"الصمد: الحي القيوم الذي لا زوال له، الذي تصمد إليه الخلائق في حوائجها.","source":"جامع البيان للطبري (24/691)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"samad","word":"الصَّمَد","root":"ص م د","category":"العقيدة","meaning":"السيد العظيم الذي انتهى سؤدده وعظمته، والذي تصمد إليه الخلائق قاطبة في حوائجها ورغائبها، والغني بذاته عن كل ما سواه سبحانه، الذي لا جوف له ولا يطعم.","ayahs":[{"surah":112,"ayah":2,"surahName":"الإخلاص","text":"اللَّهُ الصَّمَدُ","tafsir":"تفسير السعدي: أي المقصود في جميع الحوائج؛ فأهل السماوات والأرض مفتقرون إليه غاية الافتقار، يسألونه حوائجهم ويعولون عليه في أمورهم، لأنه الكامل في أوصافه العليم الذي كمل في علمه، الرحيم الذي كمل في رحمته.","source":"تيسير الكريم الرحمن (ص 937)","wajh":"إثبات كمال غنى الرب تبارك وتعالى وكمال فقر جميع المخلوقات إليه، وتفرده سبحانه بالألوهية واستحقاق إخلاص الدعاء والاستعانة له وحده لا شريك له."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الصمد: السيد الذي قد كمل في سؤدده، والشريف الذي قد كمل في شرفه، والعظيم الذي قد كمل في عظمته، وهو الله سبحانه، هذه صفته لا تنبغي إلا له.","source":"تفسير ابن كثير (8/500)"},{"scholar":"الحسن البصري رحمه الله","text":"الصمد: الحي القيوم الذي لا زوال له، الذي تصمد إليه الخلائق في حوائجها.","source":"جامع البيان للطبري (24/691)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
