insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'hanif', 'الْحَنِيف', 'العقيدة', 'تفسير القرآن العظيم (3/386)', '{"id":"hanif","word":"الْحَنِيف","root":"ح ن ف","category":"العقيدة","meaning":"المائل عن الشرك والباطل قصداً إلى التوحيد والإخلاص والاستقامة على دين الله تبارك وتعالى؛ والمقبل على ربه المعرض عن كل ما سواه.","ayahs":[{"surah":6,"ayah":161,"surahName":"الأنعام","text":"قُلْ إِنَّنِي هَدَانِي رَبِّي إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَاهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tafsir":"تفسير ابن كثير: أي مائلاً عن الشرك إلى التوحيد الخالص؛ ولهذا عقب بقوله تعالى: ﴿وما كان من المشركين﴾ تأكيداً لبراءته من الشرك وأهله.","source":"تفسير القرآن العظيم (3/386)","wajh":"ملة إبراهيم الخليل عليه السلام هي الحنيفية السمحة القائمة على إفراد الله بالعبودية والمفاصلة التامة للشرك والمشركين."},{"surah":2,"ayah":135,"surahName":"البقرة","text":"وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا ۗ قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tafsir":"تفسير السعدي: الحنيفية هي الاستقامة على الإخلاص لله والانحراف والميل عن كل طريق وضلال يخالف التوحيد.","source":"تيسير الكريم الرحمن (ص 68)","wajh":"رد دعوى أهل الكتاب بأن الهداية في التحزب أو التبديل؛ وبيان أن الهداية الحقيقية منحصرة في حنيفية التوحيد وبراءة الشرك."}],"quotes":[{"scholar":"مجاهد بن جبر رحمه الله","text":"الحنيف: المتبع لإبراهيم عليه السلام في إخلاص العبادة لله وحده لا شريك له.","source":"تفسير مجاهد (ص 95)"},{"scholar":"الإمام ابن القيم رحمه الله","text":"الحنيف: هو المقبل على الله المعرض عن كل ما سواه، قد وجّه وجهه وقلبه وعمله لله رغباً ورهباً.","source":"مدارج السالكين (3/448)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"hanif","word":"الْحَنِيف","root":"ح ن ف","category":"العقيدة","meaning":"المائل عن الشرك والباطل قصداً إلى التوحيد والإخلاص والاستقامة على دين الله تبارك وتعالى؛ والمقبل على ربه المعرض عن كل ما سواه.","ayahs":[{"surah":6,"ayah":161,"surahName":"الأنعام","text":"قُلْ إِنَّنِي هَدَانِي رَبِّي إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَاهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tafsir":"تفسير ابن كثير: أي مائلاً عن الشرك إلى التوحيد الخالص؛ ولهذا عقب بقوله تعالى: ﴿وما كان من المشركين﴾ تأكيداً لبراءته من الشرك وأهله.","source":"تفسير القرآن العظيم (3/386)","wajh":"ملة إبراهيم الخليل عليه السلام هي الحنيفية السمحة القائمة على إفراد الله بالعبودية والمفاصلة التامة للشرك والمشركين."},{"surah":2,"ayah":135,"surahName":"البقرة","text":"وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا ۗ قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ الْمُشْرِكِينَ","tafsir":"تفسير السعدي: الحنيفية هي الاستقامة على الإخلاص لله والانحراف والميل عن كل طريق وضلال يخالف التوحيد.","source":"تيسير الكريم الرحمن (ص 68)","wajh":"رد دعوى أهل الكتاب بأن الهداية في التحزب أو التبديل؛ وبيان أن الهداية الحقيقية منحصرة في حنيفية التوحيد وبراءة الشرك."}],"quotes":[{"scholar":"مجاهد بن جبر رحمه الله","text":"الحنيف: المتبع لإبراهيم عليه السلام في إخلاص العبادة لله وحده لا شريك له.","source":"تفسير مجاهد (ص 95)"},{"scholar":"الإمام ابن القيم رحمه الله","text":"الحنيف: هو المقبل على الله المعرض عن كل ما سواه، قد وجّه وجهه وقلبه وعمله لله رغباً ورهباً.","source":"مدارج السالكين (3/448)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
