insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'suht', 'السُّحْت', 'الأحكام', 'تيسير الكريم الرحمن (ص 232)', '{"id":"suht","word":"السُّحْت","root":"س ح ت","category":"الأحكام","meaning":"كل مال خبيث حُصّل بوجه محرم شرعاً يسحت الطاعات ويمحق البركات ويستوجب سخط الله وعقابه، كالرشوة والربا وثمن المحرمات.","ayahs":[{"surah":5,"ayah":42,"surahName":"المائدة","text":"سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ","tafsir":"تفسير السعدي: أي يأكلون الحرام بأي وجه كان كالرشوة في الأحكام وأخذ أموال الناس بالباطل؛ فالسحت هو المال المحرم الذي يسحت دين صاحبه وبركة كسبه.","source":"تيسير الكريم الرحمن (ص 232)","wajh":"اقتران استماع الكذب بأكل السحت دليل على أن فساد اللسان بالباطل يتبعه فساد الكسب بأكل الحرام؛ وفي ذلك أغلظ الزجر عن الرشوة والمال الحرام."}],"quotes":[{"scholar":"عبد الله بن مسعود رضي الله عنه","text":"سُئل ابن مسعود عن السحت فقال: هو الرشوة في الحكم، ومن أخذ الرشوة في الحكم فقد كفر.","source":"رواه الطبري وابن أبي شيبة بإسناد صحيح"},{"scholar":"علي بن أبي طالب رضي الله عنه","text":"السحت: الرشوة في الحكم، ومهر البغي، وعسب الفحل، وحلوان الكاهن.","source":"مصنف ابن أبي شيبة (4/293)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"suht","word":"السُّحْت","root":"س ح ت","category":"الأحكام","meaning":"كل مال خبيث حُصّل بوجه محرم شرعاً يسحت الطاعات ويمحق البركات ويستوجب سخط الله وعقابه، كالرشوة والربا وثمن المحرمات.","ayahs":[{"surah":5,"ayah":42,"surahName":"المائدة","text":"سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ","tafsir":"تفسير السعدي: أي يأكلون الحرام بأي وجه كان كالرشوة في الأحكام وأخذ أموال الناس بالباطل؛ فالسحت هو المال المحرم الذي يسحت دين صاحبه وبركة كسبه.","source":"تيسير الكريم الرحمن (ص 232)","wajh":"اقتران استماع الكذب بأكل السحت دليل على أن فساد اللسان بالباطل يتبعه فساد الكسب بأكل الحرام؛ وفي ذلك أغلظ الزجر عن الرشوة والمال الحرام."}],"quotes":[{"scholar":"عبد الله بن مسعود رضي الله عنه","text":"سُئل ابن مسعود عن السحت فقال: هو الرشوة في الحكم، ومن أخذ الرشوة في الحكم فقد كفر.","source":"رواه الطبري وابن أبي شيبة بإسناد صحيح"},{"scholar":"علي بن أبي طالب رضي الله عنه","text":"السحت: الرشوة في الحكم، ومهر البغي، وعسب الفحل، وحلوان الكاهن.","source":"مصنف ابن أبي شيبة (4/293)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
