insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'rijz', 'الرِّجْز', 'العقيدة والأحكام', 'تفسير القرآن العظيم (8/261)', '{"id":"rijz","word":"الرِّجْز","root":"ر ج ز","category":"العقيدة والأحكام","meaning":"العذاب الشديد المقلق الموجع؛ ويُطلق شرعاً على الأوثان والأنصاب والشرك والمعاصي التي تسبب هذا العذاب وتجلبه.","ayahs":[{"surah":74,"ayah":5,"surahName":"المدثر","text":"وَالرُّجْزَ فَاهْجُرْ","tafsir":"تفسير ابن كثير: أي الأوثان والأنصاب والأصنام والمعاصي كلها؛ اهجرها وافرر منها واخلع الأنداد ولا تقربها أبداً.","source":"تفسير القرآن العظيم (8/261)","wajh":"أمر النبي ﷺ بالهجران القاطع للشرك وأسبابه وأهله في مستهل بعثته؛ لبيان أن التخلية عن الشرك سابقة على كل عمل ودعوة."},{"surah":7,"ayah":134,"surahName":"الأعراف","text":"وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ","tafsir":"تفسير الطبري: الرجز هاهنا هو العذاب والنقمة التي أرسلها الله على آل فرعون كالطوفان والجراد والقمل والضفادع والدم آيات مفصلات.","source":"جامع البيان (13/66)","wajh":"بيان سنة الله المطردة في معاقبة المكذبين بالرجز والعذاب المستأصل إن تمادوا في طغيانهم واستكبارهم."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الرجز: الأوثان والشرك، أمر الله نبيه أن يهجرها ولا يقربها.","source":"تفسير البغوي (8/266)"},{"scholar":"قتادة ومجاهد رحمهما الله","text":"الرجز: الأصنام وإساف ونائلة والأنداد كلها؛ اهجر معصية الله واخلع الشرك.","source":"تفسير الطبري (23/411)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"rijz","word":"الرِّجْز","root":"ر ج ز","category":"العقيدة والأحكام","meaning":"العذاب الشديد المقلق الموجع؛ ويُطلق شرعاً على الأوثان والأنصاب والشرك والمعاصي التي تسبب هذا العذاب وتجلبه.","ayahs":[{"surah":74,"ayah":5,"surahName":"المدثر","text":"وَالرُّجْزَ فَاهْجُرْ","tafsir":"تفسير ابن كثير: أي الأوثان والأنصاب والأصنام والمعاصي كلها؛ اهجرها وافرر منها واخلع الأنداد ولا تقربها أبداً.","source":"تفسير القرآن العظيم (8/261)","wajh":"أمر النبي ﷺ بالهجران القاطع للشرك وأسبابه وأهله في مستهل بعثته؛ لبيان أن التخلية عن الشرك سابقة على كل عمل ودعوة."},{"surah":7,"ayah":134,"surahName":"الأعراف","text":"وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قَالُوا يَا مُوسَى ادْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ","tafsir":"تفسير الطبري: الرجز هاهنا هو العذاب والنقمة التي أرسلها الله على آل فرعون كالطوفان والجراد والقمل والضفادع والدم آيات مفصلات.","source":"جامع البيان (13/66)","wajh":"بيان سنة الله المطردة في معاقبة المكذبين بالرجز والعذاب المستأصل إن تمادوا في طغيانهم واستكبارهم."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"الرجز: الأوثان والشرك، أمر الله نبيه أن يهجرها ولا يقربها.","source":"تفسير البغوي (8/266)"},{"scholar":"قتادة ومجاهد رحمهما الله","text":"الرجز: الأصنام وإساف ونائلة والأنداد كلها؛ اهجر معصية الله واخلع الشرك.","source":"تفسير الطبري (23/411)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
