insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'zulm', 'الظُّلْم (الأكبر والأصغر)', 'العقيدة', 'تفسير القرآن العظيم (6/334)', '{"id":"zulm","word":"الظُّلْم (الأكبر والأصغر)","root":"ظ ل م","category":"العقيدة","meaning":"وضع الشيء في غير موضعه اللائق به شرعاً؛ وأعظمه وأخطره: الشرك بالله تعالى (الظلم الأكبر الذي لا يغفره الله إلا بالتوبة)، ويليه ظلم العبد لنفسه بالمعاصي، وظلم العباد لبعضهم في دمائهم وأموالهم وأعراضهم.","ayahs":[{"surah":31,"ayah":13,"surahName":"لقمان","text":"وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ ۖ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ","tafsir":"تفسير ابن كثير: إن الشرك أعظم الظلم لأن المشرك سوّى المخلوق الناقص الفقير بالخالق العظيم الغني، وصرف خالص حق الله لغيره.","source":"تفسير القرآن العظيم (6/334)","wajh":"تصريح القرآن القطعي بأن أعظم الظلم هو الشرك، وأن الحكمة تقتضي البدء بالتحذير منه قبل سائر الواجبات والمحرمات."},{"surah":6,"ayah":82,"surahName":"الأنعام","text":"الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُم مُّهْتَدُونَ","tafsir":"تفسير ابن كثير: لما نزلت شق ذلك على الصحابة وقالوا: أينا لم يظلم نفسه؟ فقال رسول الله ﷺ: «ليس هو كما تظنون، إنما هو كما قال لقمان لابنه: يا بني لا تشرك بالله إن الشرك لظلم عظيم» (متفق عليه).","source":"صحيح البخاري (32) ومسلم (124)","wajh":"تفسير النبي ﷺ الصريح للظلم بالشرك يقطع كل شبهة، ويدل على أن الأمن التام والهداية الكاملة في الدنيا والآخرة مشروطان بالسلامة من الشرك."}],"quotes":[{"scholar":"عبد الله بن مسعود رضي الله عنه","text":"سألت رسول الله ﷺ: أي الذنب أعظم عند الله؟ قال: «أن تجعل لله نداً وهو خلقك».","source":"صحيح البخاري برقم 4477 وصحيح مسلم برقم 86"},{"scholar":"شيخ الإسلام ابن تيمية رحمه الله","text":"الظلم ثلاثة أقسام: ظلم لا يغفره الله وهو الشرك به، وظلم لا يتركه الله وهو ظلم العباد بعضهم لبعض، وظلم يغفره الله وهو ظلم العبد لنفسه بينه وبين ربه.","source":"مجموع الفتاوى (18/166)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"zulm","word":"الظُّلْم (الأكبر والأصغر)","root":"ظ ل م","category":"العقيدة","meaning":"وضع الشيء في غير موضعه اللائق به شرعاً؛ وأعظمه وأخطره: الشرك بالله تعالى (الظلم الأكبر الذي لا يغفره الله إلا بالتوبة)، ويليه ظلم العبد لنفسه بالمعاصي، وظلم العباد لبعضهم في دمائهم وأموالهم وأعراضهم.","ayahs":[{"surah":31,"ayah":13,"surahName":"لقمان","text":"وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ ۖ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ","tafsir":"تفسير ابن كثير: إن الشرك أعظم الظلم لأن المشرك سوّى المخلوق الناقص الفقير بالخالق العظيم الغني، وصرف خالص حق الله لغيره.","source":"تفسير القرآن العظيم (6/334)","wajh":"تصريح القرآن القطعي بأن أعظم الظلم هو الشرك، وأن الحكمة تقتضي البدء بالتحذير منه قبل سائر الواجبات والمحرمات."},{"surah":6,"ayah":82,"surahName":"الأنعام","text":"الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُم بِظُلْمٍ أُولَٰئِكَ لَهُمُ الْأَمْنُ وَهُم مُّهْتَدُونَ","tafsir":"تفسير ابن كثير: لما نزلت شق ذلك على الصحابة وقالوا: أينا لم يظلم نفسه؟ فقال رسول الله ﷺ: «ليس هو كما تظنون، إنما هو كما قال لقمان لابنه: يا بني لا تشرك بالله إن الشرك لظلم عظيم» (متفق عليه).","source":"صحيح البخاري (32) ومسلم (124)","wajh":"تفسير النبي ﷺ الصريح للظلم بالشرك يقطع كل شبهة، ويدل على أن الأمن التام والهداية الكاملة في الدنيا والآخرة مشروطان بالسلامة من الشرك."}],"quotes":[{"scholar":"عبد الله بن مسعود رضي الله عنه","text":"سألت رسول الله ﷺ: أي الذنب أعظم عند الله؟ قال: «أن تجعل لله نداً وهو خلقك».","source":"صحيح البخاري برقم 4477 وصحيح مسلم برقم 86"},{"scholar":"شيخ الإسلام ابن تيمية رحمه الله","text":"الظلم ثلاثة أقسام: ظلم لا يغفره الله وهو الشرك به، وظلم لا يتركه الله وهو ظلم العباد بعضهم لبعض، وظلم يغفره الله وهو ظلم العبد لنفسه بينه وبين ربه.","source":"مجموع الفتاوى (18/166)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
