insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'nifaq', 'النِّفَاق (الاعتقادي والعملي)', 'العقيدة', 'تيسير الكريم الرحمن (ص 211)', '{"id":"nifaq","word":"النِّفَاق (الاعتقادي والعملي)","root":"ن ف ق","category":"العقيدة","meaning":"إظهار الخير وإبطان الشر؛ وهو قسمان: نفاق اعتقادي أكبر (مخرج من الملة وصاحبه في الدرك الأسفل من النار)، ونفاق عملي أصغر (اتصاف المسلم ببعض خصال المنافقين كالكذب في الحديث وإخلاف الوعد وخيانة الأمانة مع بقاء أصل الإيمان).","ayahs":[{"surah":4,"ayah":145,"surahName":"النساء","text":"إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا","tafsir":"تفسير السعدي: هذا جزاء أهل النفاق الاعتقادي؛ لأنهم أشد عداوة للمسلمين ومكراً بدين الله من الكفار المجاهرين، فكان عذابهم أغلظ وأسفل عذاب.","source":"تيسير الكريم الرحمن (ص 211)","wajh":"بيان خطورة النفاق الأكبر وأنه أشد جرماً من الكفر الصريح لما فيه من الخداع والطعن في خاصرة الأمة والتستر باسم الإسلام."},{"surah":2,"ayah":8,"surahName":"البقرة","text":"وَمِنَ النَّاسِ مَن يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ وَمَا هُم بِمُؤْمِنِينَ ۝ يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا وَمَا يَخْدَعُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ","tafsir":"تفسير ابن كثير: نعت الله المنافقين بالمخادعة والكذب؛ يظهرون الإيمان بألسنتهم لتسلم دماؤهم وأموالهم وقلوبهم منطوية على التكذيب والشك.","source":"تفسير القرآن العظيم (1/178)","wajh":"نفي الإيمان الحقيقي عنهم صراحة وفضح دعواهم الزائفة، والتحذير الصارم من سلوك طريق الخداع والتلوّن في دين الله."}],"quotes":[{"scholar":"حذيفة بن اليمان رضي الله عنه (أمين سر النبي ﷺ)","text":"المنافقون اليوم أشر منهم على عهد رسول الله ﷺ؛ كانوا يومئذ يخفونه وهم اليوم يعلنونه.","source":"صحيح البخاري برقم 7113"},{"scholar":"الحسن البصري رحمه الله","text":"ما أمن النفاق إلا منافق، وما خافه إلا مؤمن.","source":"صحيح البخاري تعليقاً في كتاب الإيمان"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"nifaq","word":"النِّفَاق (الاعتقادي والعملي)","root":"ن ف ق","category":"العقيدة","meaning":"إظهار الخير وإبطان الشر؛ وهو قسمان: نفاق اعتقادي أكبر (مخرج من الملة وصاحبه في الدرك الأسفل من النار)، ونفاق عملي أصغر (اتصاف المسلم ببعض خصال المنافقين كالكذب في الحديث وإخلاف الوعد وخيانة الأمانة مع بقاء أصل الإيمان).","ayahs":[{"surah":4,"ayah":145,"surahName":"النساء","text":"إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا","tafsir":"تفسير السعدي: هذا جزاء أهل النفاق الاعتقادي؛ لأنهم أشد عداوة للمسلمين ومكراً بدين الله من الكفار المجاهرين، فكان عذابهم أغلظ وأسفل عذاب.","source":"تيسير الكريم الرحمن (ص 211)","wajh":"بيان خطورة النفاق الأكبر وأنه أشد جرماً من الكفر الصريح لما فيه من الخداع والطعن في خاصرة الأمة والتستر باسم الإسلام."},{"surah":2,"ayah":8,"surahName":"البقرة","text":"وَمِنَ النَّاسِ مَن يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ وَمَا هُم بِمُؤْمِنِينَ ۝ يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا وَمَا يَخْدَعُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ","tafsir":"تفسير ابن كثير: نعت الله المنافقين بالمخادعة والكذب؛ يظهرون الإيمان بألسنتهم لتسلم دماؤهم وأموالهم وقلوبهم منطوية على التكذيب والشك.","source":"تفسير القرآن العظيم (1/178)","wajh":"نفي الإيمان الحقيقي عنهم صراحة وفضح دعواهم الزائفة، والتحذير الصارم من سلوك طريق الخداع والتلوّن في دين الله."}],"quotes":[{"scholar":"حذيفة بن اليمان رضي الله عنه (أمين سر النبي ﷺ)","text":"المنافقون اليوم أشر منهم على عهد رسول الله ﷺ؛ كانوا يومئذ يخفونه وهم اليوم يعلنونه.","source":"صحيح البخاري برقم 7113"},{"scholar":"الحسن البصري رحمه الله","text":"ما أمن النفاق إلا منافق، وما خافه إلا مؤمن.","source":"صحيح البخاري تعليقاً في كتاب الإيمان"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
