insert into public.content_items (kind, slot, title, category, source, data, published_data, published_at, status, approver_names)
values ('vocab', 'kufr', 'الْكُفْر (الأكبر والأصغر)', 'العقيدة', 'تفسير القرآن العظيم (1/692)', '{"id":"kufr","word":"الْكُفْر (الأكبر والأصغر)","root":"ك ف ر","category":"العقيدة","meaning":"أصله في لغة العرب: الستر والتغطية؛ وفي الشرع: نقيض الإيمان. وهو قسمان: كفر أكبر مخرج من ملة الإسلام (كتكذيب الرسل أو الاستكبار أو الشك أو الإعراض)، وكفر أصغر لا يخرج من الملة ويُسمى كفران النعمة أو كفر العمل (كقتال المسلم أو الطعن في الأنساب).","ayahs":[{"surah":2,"ayah":257,"surahName":"البقرة","text":"وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُم مِّنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ","tafsir":"تفسير ابن كثير: يبين الله حال الكفار وأن وليهم الطاغوت الذي يزين لهم الضلالات ويوردهم موارد الهلكة والخلود المؤبد في النار.","source":"تفسير القرآن العظيم (1/692)","wajh":"دلالة صريحة على أن الكفر الأكبر يوجب الخلود الدائم في النار ويسلب ولاية الله الخاصة عن العبد."},{"surah":16,"ayah":112,"surahName":"النحل","text":"وَضَرَبَ اللَّهُ مَثَلًا قَرْيَةً كَانَتْ آمِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ اللَّهِ فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ","tafsir":"تفسير السعدي: كفرت بأنعم الله أي جحدت نعمه ولم تشكرها وتصرفها في طاعته، فعاقبهم الله بالجوع والخوف بعد الأمن والرخاء.","source":"تيسير الكريم الرحمن (ص 452)","wajh":"إطلاق الكفر هنا على كفران النعمة وجحودها، وهو من الكفر الأصغر العملي الذي لا يخرج من الملة لكنه سبب زوال النعم وحلول النقم."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"في قوله تعالى: ﴿ومن لم يحكم بما أنزل الله فأولئك هم الكافرون﴾ قال: ليس بالكفر الذي تذهبون إليه، إنه كفر دون كفر.","source":"رواه الحاكم في المستدرك وصححه والذهبي"},{"scholar":"إمام أهل السنة أحمد بن حنبل رحمه الله","text":"الكفر كفران: كفر ينقل عن الملة، وكفر لا ينقل عن الملة؛ مثل قوله ﷺ: «سباب المسلم فسوق وقتاله كفر»، ومثل كفران النعمة.","source":"مسائل الإمام أحمد برواية أبي داود (ص 278)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, '{"id":"kufr","word":"الْكُفْر (الأكبر والأصغر)","root":"ك ف ر","category":"العقيدة","meaning":"أصله في لغة العرب: الستر والتغطية؛ وفي الشرع: نقيض الإيمان. وهو قسمان: كفر أكبر مخرج من ملة الإسلام (كتكذيب الرسل أو الاستكبار أو الشك أو الإعراض)، وكفر أصغر لا يخرج من الملة ويُسمى كفران النعمة أو كفر العمل (كقتال المسلم أو الطعن في الأنساب).","ayahs":[{"surah":2,"ayah":257,"surahName":"البقرة","text":"وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُم مِّنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ","tafsir":"تفسير ابن كثير: يبين الله حال الكفار وأن وليهم الطاغوت الذي يزين لهم الضلالات ويوردهم موارد الهلكة والخلود المؤبد في النار.","source":"تفسير القرآن العظيم (1/692)","wajh":"دلالة صريحة على أن الكفر الأكبر يوجب الخلود الدائم في النار ويسلب ولاية الله الخاصة عن العبد."},{"surah":16,"ayah":112,"surahName":"النحل","text":"وَضَرَبَ اللَّهُ مَثَلًا قَرْيَةً كَانَتْ آمِنَةً مُّطْمَئِنَّةً يَأْتِيهَا رِزْقُهَا رَغَدًا مِّن كُلِّ مَكَانٍ فَكَفَرَتْ بِأَنْعُمِ اللَّهِ فَأَذَاقَهَا اللَّهُ لِبَاسَ الْجُوعِ وَالْخَوْفِ بِمَا كَانُوا يَصْنَعُونَ","tafsir":"تفسير السعدي: كفرت بأنعم الله أي جحدت نعمه ولم تشكرها وتصرفها في طاعته، فعاقبهم الله بالجوع والخوف بعد الأمن والرخاء.","source":"تيسير الكريم الرحمن (ص 452)","wajh":"إطلاق الكفر هنا على كفران النعمة وجحودها، وهو من الكفر الأصغر العملي الذي لا يخرج من الملة لكنه سبب زوال النعم وحلول النقم."}],"quotes":[{"scholar":"عبد الله بن عباس رضي الله عنهما","text":"في قوله تعالى: ﴿ومن لم يحكم بما أنزل الله فأولئك هم الكافرون﴾ قال: ليس بالكفر الذي تذهبون إليه، إنه كفر دون كفر.","source":"رواه الحاكم في المستدرك وصححه والذهبي"},{"scholar":"إمام أهل السنة أحمد بن حنبل رحمه الله","text":"الكفر كفران: كفر ينقل عن الملة، وكفر لا ينقل عن الملة؛ مثل قوله ﷺ: «سباب المسلم فسوق وقتاله كفر»، ومثل كفران النعمة.","source":"مسائل الإمام أحمد برواية أبي داود (ص 278)"}],"level":1,"reviewers":["هيئة التدقيق العلمي"],"reviewedAt":"1448 هـ"}'::jsonb, now(), 'published', array['هيئة التدقيق العلمي'])
